<?php
require_once __DIR__ . '/includes/functions.php'; require_login(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{if($action==='save'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');if($name==='')throw new RuntimeException('Category name is required.');if($id){$s=$pdo->prepare('UPDATE categories SET name=? WHERE id=?');$s->execute([$name,$id]);}else{$s=$pdo->prepare('INSERT INTO categories(name) VALUES(?)');$s->execute([$name]);}flash('Category saved.');}elseif($action==='delete'){$s=$pdo->prepare('DELETE FROM categories WHERE id=?');$s->execute([(int)$_POST['id']]);flash('Category deleted.');}}catch(Throwable $e){flash('Could not save category. It may already exist or be assigned to a product.','error');}redirect('categories.php');}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM categories WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$rows=$pdo->query('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();$page_title='Categories';require 'includes/header.php'; ?>
<?php if(isset($_GET['add'])||$edit): ?><section class="panel form-panel"><h3><?= $edit?'Edit':'Add' ?> category</h3><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><input name="name" required placeholder="Category name" value="<?= e($edit['name']??'') ?>"><button class="btn primary">Save</button><a class="btn secondary" href="categories.php">Cancel</a></form></section><?php endif; ?>
<div class="page-actions"><span class="muted">Organize products into groups.</span><a class="btn primary" href="categories.php?add=1">＋ Add category</a></div>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Category</th><th>Products</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td class="strong"><?= e($r['name']) ?></td><td><?= (int)$r['product_count'] ?></td><td class="actions"><a href="categories.php?edit=<?= $r['id'] ?>">Edit</a><form method="post" data-confirm="Delete this category?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $r['id'] ?>"><button class="link danger">Delete</button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="3" class="empty">No categories yet.</td></tr><?php endif; ?></tbody></table></div></section>
<?php require 'includes/footer.php'; ?>
